    seen = [[False] * C for _ in range(R)]
    comps = []

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 4 and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if inb(nx, ny) and grid[nx][ny] == 4 and not seen[nx][ny]:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                comps.append(cells)

    def get_markers(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        markers = []
        cellset = set(cells)
        for r in range(max(0, r0 - 1), min(R, r1 + 2)):
            for c in range(max(0, c0 - 1), min(C, c1 + 2)):
                v = grid[r][c]
                if v in (1, 2, 3) and (r, c) not in cellset:
                    markers.append((r, c, v))
        return markers

    comp_infos = []
    for cells in comps:
        markers = get_markers(cells)
        color_set = set(v for _, _, v in markers)
        comp_infos.append({
            "cells": cells,
            "markers": markers,
            "colors": color_set,
        })

    # Choose the exemplar: component containing all marker colors 1,2,3 if possible,
    # otherwise the richest one.
    exemplar = None
    for info in comp_infos:
        if {1, 2, 3}.issubset(info["colors"]):
            exemplar = info
            break
    if exemplar is None:
