        if kind == 0:   # identity
            return (r, c)
        if kind == 1:   # rot 90
            return (c, -r)
        if kind == 2:   # rot 180
            return (-r, -c)
        if kind == 3:   # rot 270
            return (-c, r)
        if kind == 4:   # reflect vertical axis
            return (r, -c)
        if kind == 5:   # reflect + rot 90
            return (c, r)
        if kind == 6:   # reflect + rot 180
            return (-r, c)
        if kind == 7:   # reflect + rot 270
            return (-c, -r)

    def normalize_cells(cells):
        minr = min(r for r, c in cells)
        minc = min(c for r, c in cells)
        return sorted((r - minr, c - minc) for r, c in cells), minr, minc

    def transform_shape(cells, kind):
        t = [transform_point(r, c, kind) for r, c in cells]
        norm, _, _ = normalize_cells(t)
        return norm

