        return [(r - minr, c - minc, v) for r, c, v in t]

    base_norm = sorted(base_cells)

    out = [row[:] for row in grid]

    for info in comp_infos:
        if info is exemplar:
            continue

        cells_abs = info["cells"]
        trs = [r for r, _ in cells_abs]
        tcs = [c for _, c in cells_abs]
        tminr, tminc = min(trs), min(tcs)
        target_norm = sorted((r - tminr, c - tminc) for r, c in cells_abs)

        chosen_kind = None
